{"content":"/* ===== 科学计算器 - 仿 Win11 深色风格 ===== */
* { margin: 0; padding: 0; box-sizing: border-box; user-select: none; }

:root {
  --bg: #1c1c1e;
  --panel: #2b2b2e;
  --key-num: #3b3b3f;
  --key-num-hover: #4a4a4f;
  --key-fn: #323235;
  --key-fn-hover: #404044;
  --key-equals: #f5c6d0;
  --key-equals-hover: #fadde4;
  --text: #f2f2f2;
  --text-dim: #9a9a9e;
  --accent: #ff6b81;
  --border: rgba(255,255,255,0.08);
}

body {
  background: #101012;
  display: flex; align-items: center; justify-content: center;
  min-height: 100vh;
  font-family: "Segoe UI", "Microsoft YaHei", sans-serif;
}

.calculator {
  width: 440px; height: 860px;
  background: var(--bg);
  border-radius: 12px;
  overflow: hidden;
  display: flex; flex-direction: column;
  box-shadow: 0 20px 60px rgba(0,0,0,.6);
  position: relative;
}

/* --- 顶栏 --- */
.topbar {
  display: flex; align-items: center;
  padding: 14px 16px 6px;
  gap: 12px;
}
.icon-btn {
  background: none; border: none; color: var(--text);
  font-size: 18px; cursor: pointer; padding: 4px 8px; border-radius: 6px;
}
.icon-btn:hover { background: rgba(255,255,255,.08); }
.title { font-size: 20px; font-weight: 600; }

/* --- 显示区 --- */
.display-area {
  padding: 10px 20px 8px;
  min-height: 120px;
  display: flex; flex-direction: column; justify-content: flex-end;
  text-align: right;
}
.expression { color: var(--text-dim); font-size: 15px; min-height: 22px; word-break: break-all; }
.result {
  color: var(--text); font-size: 52px; font-weight: 600;
  word-break: break-all; line-height: 1.15;
}
.result.error { color: var(--accent); font-size: 24px; }

/* --- DEG / F-E --- */
.mode-row {
  display: flex; gap: 36px; padding: 4px 20px 8px;
}
.mode-btn {
  background: none; border: none; color: var(--text);
  font-size: 16px; cursor: pointer; padding: 4px; border-radius: 4px;
}
.mode-btn:hover { background: rgba(255,255,255,.08); }

/* --- 记忆行 --- */
.memory-row {
  display: flex; padding: 4px 8px;
  border-bottom: 1px solid var(--border);
}
.mem-btn {
  flex: 1; background: none; border: none; color: var(--text);
  font-size: 15px; padding: 10px 0; cursor: pointer; border-radius: 4px;
}
.mem-btn:hover:not(.disabled) { background: rgba(255,255,255,.08); }
.mem-btn.disabled { color: var(--text-dim); cursor: default; }
.mem-btn.arrow { color: var(--text-dim); }

/* --- 下拉菜单行 --- */
.menu-row {
  display: flex; gap: 20px; padding: 8px 14px; position: relative;
  border-bottom: 1px solid var(--border);
}
.dropdown { position: relative; }
.dropdown-toggle {
  background: none; border: none; color: var(--text);
  font-size: 15px; cursor: pointer; padding: 6px 8px; border-radius: 6px;
  display: flex; align-items: center; gap: 6px;
}
.dropdown-toggle:hover { background: rgba(255,255,255,.08); }
.dropdown-toggle i { font-family: Georgia, serif; font-style: italic; }
.dropdown-panel {
  position: absolute; top: 110%; left: 0; z-index: 20;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 4px; padding: 8px;
  min-width: 220px;
  box-shadow: 0 10px 30px rgba(0,0,0,.5);
}
.dropdown-panel.hidden { display: none; }
.dropdown-panel button {
  background: var(--key-fn); color: var(--text);
  border: none; border-radius: 6px;
  padding: 10px 14px; font-size: 15px; cursor: pointer;
}
.dropdown-panel button:hover { background: var(--key-fn-hover); }

/* --- 键盘 --- */
.keypad {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  grid-auto-rows: 1fr;
  gap: 5px;
  padding: 8px;
}
.key {
  border: none; border-radius: 6px;
  background: var(--key-fn); color: var(--text);
  font-size: 19px; cursor: pointer;
  font-family: "Segoe UI", "Microsoft YaHei", sans-serif;
  transition: background .1s;
}
.key.num { background: var(--key-num); font-size: 21px; }
.key.op { font-size: 22px; }
.key:hover { background: var(--key-fn-hover); }
.key.num:hover { background: var(--key-num-hover); }
.key:active { background: rgba(255,255,255,.18); }
.key.equals { background: var(--key-equals); color: #1c1c1e; font-size: 24px; }
.key.equals:hover { background: var(--key-equals-hover); }
.key sup { font-size: 12px; }

/* --- 历史面板 --- */
.history-panel {
  position: absolute; top: 0; right: 0; bottom: 0;
  width: 320px; background: var(--panel);
  border-left: 1px solid var(--border);
  z-index: 30;
  display: flex; flex-direction: column;
  box-shadow: -10px 0 30px rgba(0,0,0,.4);
}
.history-panel.hidden { display: none; }
.history-header {
  display: flex; justify-content: space-between; align-items: center;
  padding: 16px; font-size: 18px; font-weight: 600;
}
#historyList { list-style: none; flex: 1; overflow-y: auto; padding: 0 12px; }
#historyList li {
  padding: 10px 8px; border-radius: 6px; cursor: pointer; text-align: right;
  margin-bottom: 4px;
}
#historyList li:hover { background: rgba(255,255,255,.06); }
#historyList .h-expr { color: var(--text-dim); font-size: 13px; }
#historyList .h-res { color: var(--text); font-size: 20px; font-weight: 600; }

/* 响应式 */
@media (max-width: 480px) {
  .calculator { width: 100vw; height: 100vh; border-radius: 0; }
}
