{"content":"/* ===== 科学计算器核心逻辑 ===== */
"use strict";

/* ---------- 状态 ---------- */
const state = {
  expression: "",        // 待计算表达式（内部 token 字符串）
  result: "0",           // 显示结果
  memory: null,          // 记忆存储
  secondMode: false,     // 2nd 模式
  degMode: true,         // 角度/弧度
  feMode: false,         // 科学计数显示
  history: [],           // 历史记录
  lastAnswer: null,      // 上次结果（Ans）
  justEvaluated: false,  // 刚按过 = 
};

/* ---------- DOM ---------- */
const $ = (id) => document.getElementById(id);
const exprEl = $("expression");
const resultEl = $("result");
const historyPanel = $("historyPanel");
const historyList = $("historyList");

/* ---------- 常量 ---------- */
const PI = Math.PI, E = Math.E;

/* ================================================================
 * 表达式求值：递归下降解析器
 * 支持：+ − × ÷ mod ^ ( ) 一元负号、π/e 常量、n!、函数调用
 * ================================================================ */
function tokenize(src) {
  // 将显示符号转换为规范 token
  const tokens = [];
  let i = 0;
  while (i < src.length) {
    const ch = src[i];
    if (ch === " ") { i++; continue; }
    if (/[0-9.]/.test(ch)) {
      let num = "";
      while (i < src.length && /[0-9.]/.test(src[i])) num += src[i++];
      tokens.push({ type: "num", value: parseFloat(num) });
      continue;
    }
    if (/[a-zA-Zπ√]/.test(ch)) {
      let name = "";
      while (i < src.length && /[a-zA-Zπ√]/.test(src[i])) name += src[i++];
      tokens.push({ type: "name", value: name });
      continue;
    }
    const twoChar = src.substr(i, 2);
    if (twoChar === "%mod%") { tokens.push({ type: "op", value: "mod" }); i += 5; continue; }
    tokens.push({ type: "op", value: ch });
    i++;
  }
  return tokens;
}

function factorial(n) {
  if (n < 0 || !Number.isInteger(n)) {
    // Gamma 近似：非整数阶乘用 Lanczos
    return gamma(n + 1);
  }
  if (n > 170) return Infinity;
  let r = 1;
  for (let k = 2; k <= n; k++) r *= k;
  return r;
}

function gamma(z) {
  // Lanczos 近似
  const g = 7;
  const C = [
    0.99999999999980993, 676.5203681218851, -1259.1392167224028,
    771.32342877765313, -176.61502916214059, 12.507343278686905,
    -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7,
  ];
  if (z < 0.5) return Math.PI / (Math.sin(Math.PI * z) * gamma(1 - z));
  z -= 1;
  let x = C[0];
  for (let k = 1; k < g + 2; k++) x += C[k] / (z + k);
  const t = z + g + 0.5;
  return Math.sqrt(2 * Math.PI) * Math.pow(t, z + 0.5) * Math.exp(-t) * x;
}

/* 度数转换 */
function toRad(x) { return state.degMode ? (x * Math.PI) / 180 : x; }
function fromRad(x) { return state.degMode ? (x * 180) / Math.PI : x; }

const FUNCS = {
  sin: (x) => Math.sin(toRad(x)),
  cos: (x) => Math.cos(toRad(x)),
  tan: (x) => Math.tan(toRad(x)),
  asin: (x) => fromRad(Math.asin(x)),
  acos: (x) => fromRad(Math.acos(x)),
  atan: (x) => fromRad(Math.atan(x)),
  sinh: Math.sinh, cosh: Math.cosh, tanh: Math.tanh,
  ln: Math.log,
  log: Math.log10,
  exp: Math.exp,
  abs: Math.abs,
  sqrt: Math.sqrt,
  ceil: Math.ceil,
  floor: Math.floor,
  rand: () => Math.random(),
};

function evaluate(src) {
  const tokens = tokenize(src);
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];

  function parseExpr() {            // + −
    let v = parseTerm();
    while (peek() && peek().type === "op" && (peek().value === "+" || peek().value === "−")) {
      const op = next().value;
      const r = parseTerm();
      v = op === "+" ? v + r : v - r;
    }
    return v;
  }
  function parseTerm() {            // × ÷ mod
    let v = parseUnary();
    while (peek() && peek().type === "op" &&
          (peek().value === "×" || peek().value === "÷" || peek().value === "mod")) {
      const op = next().value;
      const r = parseUnary();
      if (op === "×") v *= r;
      else if (op === "÷") v /= r;
      else v %= r;
    }
    return v;
  }
  function parseUnary() {           // 一元负号
    if (peek() && peek().type === "op" && peek().value === "−") {
      next();
      return -parseUnary();
    }
    return parsePower();
  }
  function parsePower() {           // ^（右结合）
    const base = parsePostfix();
    if (peek() && peek().type === "op" && peek().value === "^") {
      next();
      const exp = parseUnary();   // 右结合：2^3^2 = 2^(3^2)
      return Math.pow(base, exp);
    }
    return base;
  }
  function parsePostfix() {         // n! 后缀
    let v = parsePrimary();
    while (peek() && peek().type === "op" && peek().value === "!") {
      next();
      v = factorial(v);
    }
    return v;
  }
  function parsePrimary() {
    const t = peek();
    if (!t) throw new Error("表达式不完整");
    if (t.type === "num") { next(); return t.value; }
    if (t.type === "name") {
      next();
      const name = t.value;
      if (name === "π") return PI;
      if (name === "e") return E;
      if (name === "√") {
        // √ 后跟括号或原子
        return Math.sqrt(parsePrimary());
      }
      const fn = FUNCS[name.toLowerCase()];
      if (!fn) throw new Error(`未知函数: ${name}`);
      // 函数后必须有括号参数
      if (peek() && peek().type === "op" && peek().value === "(") {
        next();
        const arg = parseExpr();
        if (!peek() || next().value !== ")") throw new Error("缺少右括号");
        return fn(arg);
      }
      // 无括号：应用于下一个原子（如 sin30）
      return fn(parsePrimary());
    }
    if (t.type === "op" && t.value === "(") {
      next();
      const v = parseExpr();
      if (!peek() || next().value !== ")") throw new Error("缺少右括号");
      return v;
    }
    throw new Error(`意外符号: ${t.value}`);
  }

  const result = parseExpr();
  if (pos < tokens.length) throw new Error(`多余符号: ${tokens[pos].value}`);
  return result;
}

/* ================================================================
 * 显示格式化
 * ================================================================ */
function formatNumber(n) {
  if (typeof n !== "number" || isNaN(n)) return "错误";
  if (!isFinite(n)) return "除数不能为零";
  // 消除浮点误差
  const rounded = parseFloat(n.toPrecision(12));
  if (state.feMode && rounded !== 0) {
    return rounded.toExponential(9).replace(/\.?0+e/, "e").replace("e+", "e");
  }
  // 大数/小数用科学计数
  if (Math.abs(rounded) >= 1e16 || (Math.abs(rounded) < 1e-10 && rounded !== 0)) {
    return rounded.toExponential(6);
  }
  return String(rounded);
}

/* ================================================================
 * 渲染
 * ================================================================ */
function render() {
  exprEl.textContent = state.expression;
  resultEl.textContent = state.result;
  resultEl.classList.remove("error");
  // 记忆按钮状态
  const hasMem = state.memory !== null;
  document.querySelectorAll('[data-mem="MC"], [data-mem="MR"]').forEach((b) =>
    b.classList.toggle("disabled", !hasMem)
  );
}

function renderError(msg) {
  resultEl.textContent = msg;
  resultEl.classList.add("error");
}

/* ================================================================
 * 求值入口
 * ================================================================ */
function evaluateCurrent() {
  if (!state.expression.trim()) return;
  try {
    const val = evaluate(state.expression);
    const formatted = formatNumber(val);
    pushHistory(state.expression, formatted);
    state.lastAnswer = val;
    state.result = formatted;
    state.expression = "";
    state.justEvaluated = true;
  } catch (err) {
    renderError(err.message || "输入无效");
    setTimeout(() => { render(); }, 1200);
  }
}

/* ================================================================
 * 按键处理
 * ================================================================ */
