const keypadEl = document.getElementById("keypad");
const degBtn = document.getElementById("degToggle");
const feBtn = document.getElementById("feToggle");
const historyPanel = document.getElementById("historyPanel");
const historyList = document.getElementById("historyList");
const historyBtn = document.getElementById("historyBtn");
const historyClear = document.getElementById("historyClear");

/* ---------- 状态 ---------- */
let currentExpr = "";        // 当前表达式（显示形式，含 × ÷ − π 等）
let currentResult = 0;       // 最近一次成功求值的结果
let justEvaluated = false;   // 刚按过 =
let degMode = true;          // true=DEG false=RAD
let feMode = false;          // F-E 科学计数显示
let secondOn = false;        // 2nd 功能键
let memoryValue = null;      // 记忆值
let history = [];            // 历史记录

/* ---------- 工具：数字格式化 ---------- */
function formatNumber(x) {
  if (typeof x !== "number" || !isFinite(x)) return null;
  if (x === 0) return "0";
  const abs = Math.abs(x);
  if (abs >= 1e16 || abs < 1e-9) {
    // 自动转科学计数
    return x.toExponential(9).replace(/\.?0+e/, "e").replace("e+", "e");
  }
  let s = parseFloat(x.toPrecision(12)).toString();
  return s;
}
function formatFE(x) {
  if (!isFinite(x)) return "无效输入";
  return x.toExponential(13).replace(/\.?0+e/, "e").replace("e+", "e");
}

/* ---------- 词法分析：显示字符串 → tokens ---------- */
