/* ---------- 自动补全/清理（用于预览与求 = ） ---------- */
function sanitize(exprStr) {
  let s = exprStr;
  // 去掉尾部悬挂的操作符
  s = s.replace(/(mod|[+−×÷^])\s*$/, "");
  // 去掉尾部未闭合的函数括号，例如 "5×sin("
  for (let guard = 0; guard < 20; guard++) {
    const m = s.match(/([a-zA-Z√∛₂]+)\($/);
    if (m) s = s.slice(0, s.length - m[0].length);
    if (/\($/.test(s)) { s = s.slice(0, -1); continue; }
    break;
  }
  s = s.replace(/(mod|[+−×÷^])\s*$/, "");
