}

/* ---------- 显示更新 ---------- */
function render() {
  exprEl.textContent = currentExpr;
  if (feMode) {
    resultEl.textContent = formatFE(currentResult);
    resultEl.classList.remove("error");
  } else {
    const f = formatNumber(currentResult);
    if (f !== null) { resultEl.textContent = f; resultEl.classList.remove("error"); }
  }
}
function showError(msg) {
  resultEl.textContent = msg;
  resultEl.classList.add("error");
}

function refreshPreview() {
  if (!currentExpr) { currentResult = 0; render(); return; }
  try {
    const v = evaluate(currentExpr, degMode);
    if (isFinite(v)) { currentResult = v; }
    render();
  } catch (e) {
    render();  // 输入过程中解析失败：保留上次结果
  }
}

/* ---------- 输入构建 ---------- */
function smartInsert(text) {
  if (justEvaluated) {
    const isOperator = /^[+−×÷^!%]|^mod$/.test(text) || text === "mod";
    currentExpr = isOperator ? formatNumber(currentResult) : "";
    justEvaluated = false;
  }
  const last = currentExpr.slice(-1);
  // 隐式乘法：操作数结尾 + 新操作数开头 → 自动 ×
  if (OPERAND_END.test(last) && text !== ")" && OPERAND_START.test(text) && !/^mod$/.test(text)) {
    // 特例：")!"、"π!" 等后缀不插乘
    currentExpr += "×";
  }
  currentExpr += text;
  refreshPreview();
}
function smartInsertNumber(nStr) {
  if (justEvaluated) { currentExpr = ""; justEvaluated = false; }
  const last = currentExpr.slice(-1);
  if (OPERAND_END.test(last)) currentExpr += "×";
  currentExpr += nStr;
  refreshPreview();
}

/* 包裹尾部操作数：square/inverse/abs/sqrt/factorial/negate 等 */
function wrapTrailingOperand(wrapFn) {
  if (justEvaluated) { currentExpr = formatNumber(currentResult); justEvaluated = false; }
  const s = currentExpr;
  if (!s) { currentExpr = "0"; }
  const str = currentExpr;
  let end = str.length;
  let operand = null;
  const mNum = str.match(/(\d+\.?\d*|π|e)$/);
  const mParen = /\)$/.test(str);
  if (mNum) {
    operand = mNum[1];
  } else if (mParen) {
    // 向前找匹配的 (
    let depth = 0, k = str.length - 1;
    for (; k >= 0; k--) {
      if (str[k] === ")") depth++;
      else if (str[k] === "(") { depth--; if (depth === 0) break; }
    }
    if (k >= 0) { operand = str.slice(k); end = k; }
  }
  if (operand === null) { refreshPreview(); return; }
  const replacement = wrapFn(operand);
  currentExpr = str.slice(0, end) + replacement;
