}

/* ---------- 按键动作 ---------- */
const ACTIONS = {
  clear() {
    currentExpr = ""; currentResult = 0; justEvaluated = false;
    render();
  },
  backspace() {
    if (justEvaluated) { currentExpr = formatNumber(currentResult) || ""; justEvaluated = false; }
    else {
      if (currentExpr.endsWith("mod")) currentExpr = currentExpr.slice(0, -3);
      else {
        // 整块删除函数名
        const m = currentExpr.match(/([a-zA-Z√∛₂]+|\d+\.?\d*)$/);
        currentExpr = currentExpr.slice(0, currentExpr.length - (m ? m[0].length : 1));
      }
    }
    refreshPreview();
  },
  equals() {
    if (!currentExpr) return;
    try {
      const v = evaluate(currentExpr, degMode);
      if (!isFinite(v)) { showError("结果未定义"); return; }
      currentResult = v;
      const exprShown = currentExpr + " =";
      const resShown = formatNumber(v);
      addHistory(exprShown, resShown);
      exprEl.textContent = exprShown;
      resultEl.textContent = feMode ? formatFE(v) : resShown;
      resultEl.classList.remove("error");
      justEvaluated = true;
    } catch (e) {
      showError(e.message || "无效输入");
