  square() { wrapTrailingOperand((op) => `(${op})^${secondOn ? 3 : 2}`); },
  inverse() { wrapTrailingOperand((op) => `1/(${op})`); },
  abs() { wrapTrailingOperand((op) => `abs(${op})`); },
  sqrt() { wrapTrailingOperand((op) => `${secondOn ? "∛" : "√"}(${op})`); },
  factorial() { wrapTrailingOperand((op) => `${op}!`); },
  exp() { wrapTrailingOperand((op) => `exp(${op})`); },
  tenpow() { smartInsert(`${secondOn ? 2 : 10}^(`); },
  log() { smartInsert(secondOn ? "log₂(" : "log("); },
  ln() { smartInsert(secondOn ? "e^(" : "ln("); },
  power() { smartInsert("^"); },
  second() {
    secondOn = !secondOn;
    updateSecondLabels();
  },
};

/* 2nd 状态更新按钮标签 */
function updateSecondLabels() {
  const map = secondOn
    ? { square: "x³", sqrt: "∛x", tenpow: "2ˣ", log: "log₂", ln: "eˣ" }
    : { square: "x²", sqrt: "√x", tenpow: "10ˣ", log: "log", ln: "In" };
  for (const [action, label] of Object.entries(map)) {
    const btn = keypadEl.querySelector(`[data-action="${action}"]`);
