      case "MR": smartInsertNumber(formatNumber(memoryValue)); break;
      case "M+": memoryValue = (memoryValue || 0) + currentResult; break;
      case "M-": memoryValue = (memoryValue || 0) - currentResult; break;
      case "MS": memoryValue = currentResult; break;
      case "Mv": toggleMemoryPanel(); break;
