  });
});

/* 记忆面板（M⌄ 下拉） */
let memPanel = null;
function toggleMemoryPanel() {
  if (memPanel) { memPanel.remove(); memPanel = null; return; }
  memPanel = document.createElement("div");
  memPanel.className = "memory-panel";
  memPanel.innerHTML = memoryValue === null
    ? `<div class="mem-empty">没有任何内容保存到内存</div>`
