         <button data-m="M-">M−</button><button data-m="MS">MS</button>
       </div>`;
  document.querySelector(".memory-row").appendChild(memPanel);
  if (memoryValue !== null) {
    memPanel.querySelector(".mem-value").addEventListener("click", () => {
      smartInsertNumber(formatNumber(memoryValue));
      toggleMemoryPanel();
    });
    memPanel.querySelectorAll(".mem-actions button").forEach((b) => {
      b.addEventListener("click", (ev) => {
        ev.stopPropagation();
        const m = b.dataset.m;
        if (m === "MC") memoryValue = null;
        if (m === "M+") memoryValue += currentResult;
        if (m === "M-") memoryValue -= currentResult;
        if (m === "MS") memoryValue = currentResult;
        updateMemoryBtns();
        toggleMemoryPanel();
      });
    });
  }
}

/* ---------- 三角学 / 函数 下拉 ---------- */
function setupDropdown(id) {
  const box = document.getElementById(id);
  const toggle = box.querySelector(".dropdown-toggle");
  const panel = box.querySelector(".dropdown-panel");
  toggle.addEventListener("click", (e) => {
    e.stopPropagation();
    document.querySelectorAll(".dropdown-panel").forEach((p) => { if (p !== panel) p.classList.add("hidden"); });
    panel.classList.toggle("hidden");
  });
  panel.addEventListener("click", (e) => { e.stopPropagation(); });
  panel.querySelectorAll("button").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (btn.dataset.fn === "rand") {
        smartInsertNumber((Math.random()).toFixed(8));
      } else if (btn.dataset.fn) {
        smartInsert(btn.dataset.fn + "(");
      } else if (btn.dataset.expr) {
        smartInsert(btn.dataset.expr);
      }
      panel.classList.add("hidden");
    });
  });
}
setupDropdown("trigMenu");
setupDropdown("funcMenu");
document.addEventListener("click", () => {
  document.querySelectorAll(".dropdown-panel").forEach((p) => p.classList.add("hidden"));
  if (memPanel) { memPanel.remove(); memPanel = null; }
});

/* ---------- 历史记录 ---------- */
function addHistory(expr, res) {
  history.unshift({ expr, res });
  renderHistory();
}
function renderHistory() {
  historyList.innerHTML = "";
  if (!history.length) {
    historyList.innerHTML = `<li class="h-empty" style="text-align:center;color:var(--text-dim);cursor:default">这里还没有历史记录</li>`;
    return;
  }
  history.forEach((h) => {
    const li = document.createElement("li");
    li.innerHTML = `<div class="h-expr">${h.expr}</div><div class="h-res">${h.res}</div>`;
    li.addEventListener("click", () => smartInsertNumber(h.res));
    historyList.appendChild(li);
  });
}
historyBtn.addEventListener("click", () => historyPanel.classList.toggle("hidden"));
historyClear.addEventListener("click", () => { history = []; renderHistory(); });

/* ---------- DEG / F-E ---------- */
degBtn.addEventListener("click", () => {
  degMode = !degMode;
  degBtn.textContent = degMode ? "DEG" : "RAD";
  refreshPreview();
});
feBtn.addEventListener("click", () => {
  feMode = !feMode;
  feBtn.classList.toggle("active-2nd", feMode);
  render();
});

/* ---------- 键盘输入绑定 ---------- */
keypadEl.addEventListener("click", (e) => {
  const btn = e.target.closest("button.key");
  if (!btn) return;
  const insert = btn.dataset.insert;
  const action = btn.dataset.action;
  if (insert === "%mod%") smartInsert("mod");
  else if (insert) smartInsert(insert);
  else if (action && ACTIONS[action]) ACTIONS[action]();
});

/* 物理键盘 */
document.addEventListener("keydown", (e) => {
  const k = e.key;
  if (/^[0-9]$/.test(k)) smartInsertNumber(k);
  else if (k === ".") smartInsertNumber(".");
  else if (k === "+") smartInsert("+");
  else if (k === "-") smartInsert("−");
  else if (k === "*") smartInsert("×");
  else if (k === "/") { e.preventDefault(); smartInsert("÷"); }
  else if (k === "^") smartInsert("^");
  else if (k === "(" || k === ")") smartInsert(k);
  else if (k === "Enter" || k === "=") { e.preventDefault(); ACTIONS.equals(); }
  else if (k === "Backspace") ACTIONS.backspace();
  else if (k === "Escape") ACTIONS.clear();
  else if (k.toLowerCase() === "p") smartInsert("π");
});

/* ---------- 启动 ---------- */
renderHistory();
updateMemoryBtns();
render();
