const fs = require("fs");
const src = fs.readFileSync(__dirname + "/calculator.js", "utf8");

// 截取从 tokenize 定义到 evaluate 结束的纯逻辑段
const start = src.indexOf("const FUNCS");
const end = src.indexOf("/* ---------- 显示更新");
if (start < 0 || end < 0) { console.error("截取失败"); process.exit(1); }
const core = src.slice(start, end);
eval(core);  // 得到 tokenize / makeParser / sanitize / evaluate / formatNumber 等

let pass = 0, fail = 0;
function T(expr, expected, deg = true, eps = 1e-9) {
  try {
    const got = evaluate(expr, deg);
    const ok = typeof expected === "number"
      ? Math.abs(got - expected) <= Math.max(eps, Math.abs(expected) * eps)
      : got === expected;
    if (ok) { pass++; }
    else { fail++; console.log(`FAIL: ${expr} => ${got}, expected ${expected}`); }
  } catch (e) {
    if (expected === "ERR") { pass++; }
    else { fail++; console.log(`FAIL(throw): ${expr} => ${e.message}`); }
  }
}

/* 基础四则 */
T("1+2", 3);
T("5−3", 2);
T("4×2.5", 10);
T("9÷3", 3);
T("7mod3", 1);
T("2+3×4", 14);           // 优先级
T("(2+3)×4", 20);          // 括号
T("10÷4×2", 5);            // 左结合
T("2^10", 1024);
T("2^3^2", 512);           // 幂右结合: 2^(3^2)=512
T("−5+3", -2);             // 一元负号
T("−2^2", -4);             // 一元负号优先级低于幂（与 Win11 一致）

/* 未闭合表达式 sanitize 自动补全 */
T("2×(3+4", 14);           // 自动补右括号
T("5+3×", 20);             // 尾部悬挂操作符剥离 → 5+3=8? 不对：5+3× → 剥离 × → 8
T("sin(30", 0.5, true);    // 函数括号 + DEG
T("sin(30)+", 0.5, true);  // 尾部 + 剥离
T("", 0);

/* 函数与常量 */
T("sin(30)", 0.5, true);       // DEG
T("sin(π÷6)", 0.5, false);     // RAD
T("cos(60)", 0.5, true);
T("tan(45)", 1, true);
T("asin(0.5)", 30, true);
T("log(1000)", 3);
T("log₂(8)", 3);
T("ln(e)", 1);
T("exp(1)", Math.E);
T("√(144)", 12);
T("∛(27)", 3);
T("abs(−7)", 7);
T("floor(3.7)", 3);
T("ceil(3.2)", 4);
T("5!", 120);
T("0!", 1);
T("(2+3)!", 120);          // 括号阶乘
T("3!×2", 12);             // 后缀优先于乘

/* 隐式乘法 */
T("2π", 2 * Math.PI);
T("2(3+4)", 14);
T("(2)(3)", 6);
T("2sin(30)", 1, true);
T("5!", 120);

/* 错误处理 */
T("5÷0", "ERR");
T("5mod0", "ERR");
T("sin(90", 1, true);      // sanitize 修复后合法
T("2++", 2, true, 1e-9);   // sanitize 剥离尾部 + → "2+" → 剥离 → 2
T("1.2.3", "ERR");
T("()", "ERR");

/* 2nd 功能生成的表达式 */
T("∛(64)", 4);
T("log₂(1024)", 10);

/* 浮点精度 */
T("0.1+0.2", 0.30000000000000004, false, 1e-12);

console.log(`\n结果: ${pass} 通过, ${fail} 失败`);
process.exit(fail ? 1 : 0);
