```

wrapTrailingOperand 的逻辑：

```js
function wrapTrailingOperand(wrapFn) {
  if (justEvaluated) { currentExpr = formatNumber(currentResult); justEvaluated = false; }
  const s = currentExpr;
  if (!s) { currentExpr = "0"; }
  const str = currentExpr;
  let end = str.length;
  let operand = null;
  const mNum = str.match(/(\d+\.?\d*|π|e)$/);
